// Write a finished table to a Parquet file.
inline void write(const std::shared_ptr<arrow::Table>& table, const std::string& path) {
    std::shared_ptr<arrow::io::FileOutputStream> file;
    auto opened = arrow::io::FileOutputStream::Open(path);
    check(opened.status(), "open " + path);
    file = *opened;

    check(::parquet::arrow::WriteTable(*table, arrow::default_memory_pool(), file, table->num_rows() > 0 ? table->num_rows() : 1024),
        "write " + path);

    check(file->Close(), "close " + path);
}

